// One versioned patch authority; descriptors are generated by the Rust crate.
// Preparation is outside process(). Trusted-host ABI pointers never leave here.
import {compilePitched,validatePitchedConfig} from './pitchedCompiler.js';
import {validatePercussionConfig} from './percussionConfig.js';
import {validatePianoConfig,PIANO_TYPES} from './pianoConfig.js';
import {validateIowaConfig,iowaFields} from './iowaConfig.js';
export const checked = code => { if (code) throw Error(`Graph rejected operation (${code})`); };
const uint = n => Number.isInteger(n) && n > 0 && n <= 0xffffffff;
const frame = n => Number.isSafeInteger(n) && n >= 0;
const finite = n => typeof n === 'number' && Number.isFinite(n);

export function validatePatch(raw, contracts) {
  // AudioWorkletGlobalScope need not expose Window/Worker structuredClone.
  const p = JSON.parse(JSON.stringify(raw));
  if (p?.version !== contracts.patchVersion || !Array.isArray(p.modules) || !p.modules.length || p.modules.length > contracts.maxNodes || !Array.isArray(p.connections) || p.connections.length > contracts.maxEdges || !Array.isArray(p.events) || p.events.length > contracts.maxEvents) throw Error('Invalid patch version or resource bounds');
  const modules = new Map(), edges = new Set(), inputs = new Set(), dependencies = new Map();
  for (const n of p.modules) {
    const d = contracts.modules.find(d => d.type === n.type && d.version === n.version);
    if (!uint(n.id) || modules.has(n.id) || !d || !n.parameters || typeof n.parameters !== 'object' || Array.isArray(n.parameters)) throw Error('Invalid module identity/contract');
    for (const [id, value] of Object.entries(n.parameters)) {
      const param = d.parameters.find(p => p.id === id);
      if (!param || !finite(value) || value < param.min || value > param.max || (['enum','boolean'].includes(param.unit)&&!Number.isInteger(value))) throw Error(`Invalid parameter ${id}`);
    }
    modules.set(n.id, d);
    if(['legacy.core','legacy.fm'].includes(d.type))n.config=validatePitchedConfig(n.config,d.type==='legacy.fm');
    if(d.type==='legacy.piano'){n.config=validatePianoConfig(n.config);if(n.version!==n.config.version)throw Error('Piano module/configuration version mismatch');}
    if(d.type==='legacy.iowa')n.config=validateIowaConfig(n.config);
    if(d.type==='legacy.percussion'){
      if(n.version===1&&n.config!==undefined||n.version===2&&n.config===undefined)throw Error('Invalid percussion kit: requires module version 2 and complete configuration');
      if(n.version===2)n.config=validatePercussionConfig(n.config,d.kitConfiguration);
    }
    dependencies.set(n.id,new Set());
  }
  for (const e of p.connections) {
    if (!uint(e.id) || edges.has(e.id) || !modules.has(e.from?.module) || !modules.has(e.to?.module)) throw Error('Invalid connection identity');
    edges.add(e.id);
    const source = modules.get(e.from.module).ports.find(p => p.id === e.from.port && p.direction === 'out');
    const target = modules.get(e.to.module);
    if (!source) throw Error('Missing output port');
    if (e.kind === 'audio') {
      const dest = target.ports.find(p => p.id === e.to.port && p.direction === 'in');
      if (!dest || source.family !== 'audio' || dest.family !== source.family || dest.channels !== source.channels) throw Error('Incompatible audio buses');
      const input=`${e.to.module}:${dest.id}`;
      if(inputs.has(input))throw Error('Duplicate input: use an explicit mixer');
      if(e.enabled!==undefined&&(typeof e.enabled!=='boolean'||dest.role!=='detector'))throw Error('Only detector connections can be disabled');
      inputs.add(input);
    } else if (e.kind === 'modulation') {
      const dest = target.parameters.find(p => p.id === e.to.parameter);
      if (source.family !== 'control' || source.channels !== 1 || !dest?.modulation || !['bipolar', 'unipolar'].includes(e.mapping) || !finite(e.depth) || Math.abs(e.depth) > 4 || !finite(e.offset) || Math.abs(e.offset) > 4) throw Error('Incompatible modulation mapping');
    } else throw Error('Unsupported connection family');
    dependencies.get(e.to.module).add(e.from.module);
  }
  if(p.modules.filter(n=>n.type==='legacy.percussion').length>8)throw Error('Percussion instance limit exceeded');
  if(p.modules.filter(n=>['legacy.core','legacy.fm','legacy.piano','legacy.iowa'].includes(n.type)).length>8)throw Error('Pitched instance limit exceeded');
  if([...modules.values()].filter(d=>d.type==='ref.output').length!==1)throw Error('Exactly one output is required');
  for(const [id,d] of modules)for(const port of d.ports)if(port.required&&!inputs.has(`${id}:${port.id}`))throw Error('Missing required input');
  const ready=new Set();
  while(ready.size<modules.size){const next=[...dependencies].find(([id,deps])=>!ready.has(id)&&[...deps].every(id=>ready.has(id)));if(!next)throw Error('Unsupported graph cycle');ready.add(next[0]);}
  const owners=new Map();
  for (const e of p.events) {eventPacket(e, modules, p.connections);if(e.kind==='note'&&e.note&&[0,1,3,5].includes(e.event)){const k=e.target+':'+e.note;if(owners.has(k)&&owners.get(k)!==e.owner)throw Error('Pitched note owner conflict');owners.set(k,e.owner);}}
  for(const n of p.modules.filter(n=>n.type==='legacy.piano')){
    const used=new Set(),ends=[],slots=[];
    for(const e of p.events.filter(e=>e.target===n.id&&e.kind==='note'&&e.event===0).sort((a,b)=>a.frame-b.frame)){
      const v=n.config.notes.find(v=>v.id===e.note);if(!v||used.has(v.id)||Math.fround(e.a)!==Math.fround(v.midi)||Math.fround(e.b)!==Math.fround(v.velocity))throw Error('Piano trigger/configuration mismatch');used.add(v.id);
      if(n.config.version===3){const prior=slots[v.voice];if(v.onsetFrame!==e.frame||prior&&prior.onsetFrame+prior.cutFrame>e.frame)throw Error('Piano slot lifetime/trigger mismatch');slots[v.voice]=v;}
      else{for(let i=ends.length-1;i>=0;i--)if(ends[i]<=e.frame)ends.splice(i,1);
       if(ends.length>=n.config.voices)throw Error('Piano voice-steal fade is not supported');ends.push(e.frame+v.gain.at(-1)[1]);}
    }
  }
  for(const n of p.modules.filter(n=>n.type==='legacy.iowa')){const used=new Set();for(const e of p.events.filter(e=>e.target===n.id&&e.kind==='note'&&e.event!==4)){const v=n.config.notes.find(v=>v.id===e.note);if(!v||e.event===0&&(used.has(v.id)||Math.fround(e.a)!==Math.fround(v.midi)||Math.fround(e.b)!==Math.fround(v.velocity)))throw Error('Iowa trigger/configuration mismatch');if(e.event===0)used.add(v.id);}}
  for(const n of p.modules)if(p.events.filter(e=>e.target===n.id&&e.kind==='note').length>4000)throw Error('Pitched note capacity exceeded');
  return p;
}

function eventPacket(e, modules, connections) {
  const d = modules.get(e.target);
  if (!frame(e.frame) || !uint(e.owner) || !d) throw Error('Invalid event frame/ownership/target');
  if(['legacy.core','legacy.fm','legacy.piano','legacy.iowa'].includes(d.type)){
    if(d.type==='legacy.iowa'&&e.kind==='note'&&(![0,1,4].includes(e.event)||e.frame%128!==0))throw Error('Iowa notes require canonical 128-frame ticks');
    if(d.type==='legacy.piano'&&e.kind==='note'&&![0,4].includes(e.event))throw Error('Unsupported finite piano event');
    if(e.kind==='cancel')return [e.frame,e.target,e.owner,4,0,0];
    if(e.kind==='note'&&Number.isInteger(e.event)&&e.event>=0&&e.event<=6&&Number.isInteger(e.note)&&e.note>=0&&e.note<=0xffffffff&&finite(e.a)&&finite(e.b)){
      const k=e.event,id=e.note,a=e.a,b=e.b;
      if(([0,1,5].includes(k)&&!id)||(k===0&&(a<0||a>127||b<0||b>1))||([2,3].includes(k)&&(a<0||a>1))||(k===5&&(a<0||a>127||b<0||b>8))||(k===6&&(id>2||a<0||a>3||b<0||b>1)))throw Error('Invalid pitched note values');
      return [e.frame,e.target,e.owner,k,id,a,b];
    }
  }
  if (e.kind === 'gate' && d.type === 'ref.tone' && typeof e.value === 'boolean') return [e.frame,e.target,e.owner,1,0,Number(e.value)];
  if (e.kind === 'hit' && d.type === 'legacy.percussion' && Number.isInteger(e.drum)&&e.drum>=0&&e.drum<14&&Number.isInteger(e.model)&&e.model>=0&&e.model<=2&&Number.isInteger(e.hit)&&e.hit>=0&&e.hit<=0xffffffff&&finite(e.velocity)&&e.velocity>=0&&e.velocity<=1&&finite(e.duration)&&e.duration>=0&&e.duration<=30&&finite(e.vary)&&Math.abs(e.vary)<=1&&finite(e.tone)&&Math.abs(e.tone)<=1&&finite(e.decay)&&e.decay>=.5&&e.decay<=2) return [e.frame,e.target,e.owner,e.drum,e.velocity,e.duration,e.vary,e.tone,e.decay,e.hit,e.model];
  if (e.kind === 'parameter') {
    const p = d.parameters.find(p => p.id === e.parameter);
    if (p && finite(e.value) && e.value >= p.min && e.value <= p.max && (!['enum','boolean'].includes(p.unit)||Number.isInteger(e.value))) return [e.frame,e.target,e.owner,0,p.code,e.value];
  }
  if (e.kind === 'modulation' && typeof e.value === 'boolean' && connections.some(c => c.id === e.edge && c.kind === 'modulation' && c.to.module === e.target)) return [e.frame,e.target,e.owner,2,e.edge,Number(e.value)];
  if(e.kind==='connection'&&typeof e.value==='boolean'&&d.type==='graph.compressor'&&connections.some(c=>c.id===e.edge&&c.kind==='audio'&&c.to.module===e.target&&c.to.port==='detector.in'))return [e.frame,e.target,e.owner,3,e.edge,Number(e.value)];
  throw Error('Invalid event contract');
}

export function savePatch(patch, contracts) { return JSON.stringify(validatePatch(patch, contracts), null, 2) + '\n'; }
export function loadPatch(text, contracts) { return validatePatch(JSON.parse(text), contracts); }

export class ReferenceGraph {
  constructor(engine, patch, contracts, sampleRate, maxBlock = 2048) {
    this.engine = engine;
    if (!Number.isInteger(maxBlock) || maxBlock < 1 || maxBlock > contracts.maxBlock) throw Error('Invalid block size');
    this.patch = validatePatch(patch, contracts);
    if(this.patch.modules.some(n=>n.type==='legacy.piano')&&sampleRate!==48000)throw Error('Prepared piano v1 requires 48 kHz');
    if(this.patch.modules.some(n=>n.type==='legacy.iowa'&&n.config.sampleRate!==sampleRate))throw Error('Prepared Iowa sample rate mismatch');
    this.contracts = contracts;
    this.modules = new Map(this.patch.modules.map(n => [n.id, contracts.modules.find(d => d.type === n.type && d.version === n.version)]));
    if (engine.graph_api() !== contracts.api) throw Error('Graph ABI mismatch');
    this.handle = engine.graph_new(sampleRate, maxBlock);
    if (!this.handle) throw Error('Invalid sample rate/block size');
    this.maxBlock = maxBlock;
    try {
      for (const n of this.patch.modules) {
        const d = this.modules.get(n.id);
        checked(engine.graph_node(this.handle,n.id,d.code,n.version));
        for (const [key,value] of Object.entries(n.parameters)) checked(engine.graph_base(this.handle,n.id,d.parameters.find(p => p.id === key).code,value));
        if(d.type==='legacy.percussion'&&n.config){
          const c=n.config;
          checked(engine.graph_percussion_config(this.handle,n.id,c.version,d.kitConfiguration.voices.indexOf(c.voice)+1));
          c.drums.forEach((v,i)=>checked(engine.graph_percussion_drum(this.handle,n.id,i,Number(v.on),v.level,v.tone,v.decay)));
        }
        if(d.type==='legacy.iowa'){
          const c=n.config;checked(engine.graph_iowa_config(this.handle,n.id,c.voices));
          for(const s of c.banks){checked(engine.graph_iowa_spec(this.handle,n.id,s.id,Number(s.kind==='decay'),s.f0??0,s.seconds??0,s.rate??0,s.depth??0,s.tremolo??0,s.pitchWander??0,s.levelWander??0));for(const [field,a]of iowaFields(s)){const ptr=engine.graph_iowa_buffer_new(a.length);if(!ptr)throw Error('Iowa preparation scratch bound exceeded');try{new Float64Array(engine.memory.buffer,engine.graph_iowa_buffer_ptr(ptr),a.length).set(a);checked(engine.graph_iowa_data(this.handle,n.id,s.id,field,ptr));}finally{engine.graph_iowa_buffer_free(ptr);}}}
          for(const v of c.notes)checked(engine.graph_iowa_note_spec(this.handle,n.id,v.id,v.bank,v.midi,v.velocity,v.gain,v.tune,Number(v.ring),v.roll?.rate??0,v.roll?.level??0,v.roll?.timing??0,v.slide?.cents??0,v.slide?.seconds??0));
        }
        if(d.type==='legacy.piano'){

          const c=n.config;checked(engine.graph_piano_config(this.handle,n.id,c.voices,c.cutoff,c.q,c.pitch,c.pitchDecay));
          for(const [i,m]of (c.controls??[]).entries()){checked(engine.graph_piano_control(this.handle,n.id,Number(m.axis==='filter'),Number(m.kind==='linear'),m.phase,m.frequency,m.initialDepth,m.targetDepth,m.tauFrames));for(const [frame,value]of m.points)checked(engine.graph_piano_control_point(this.handle,n.id,i,frame,value));}
          for(const b of c.banks)checked(engine.graph_piano_bank(this.handle,n.id,b.frequency,PIANO_TYPES.indexOf(b.type),b.decay,b.brightness,b.hammer,b.unison,b.velocity,b.seed,b.resonance,b.softness,b.sustain,b.wear));
          for(const v of c.notes){checked(engine.graph_piano_spec(this.handle,n.id,v.id,v.bank,v.midi,v.velocity));for(const p of [...v.gain,...v.filter])checked(engine.graph_piano_point(this.handle,n.id,v.id,...p));if(c.version===3)checked(engine.graph_piano_lifetime(this.handle,n.id,v.id,v.voice,v.onsetFrame,v.fadeFrame??-1,v.cutFrame));}
        }
        if(['legacy.core','legacy.fm'].includes(d.type)){
          const c=compilePitched(n.config,d.type==='legacy.fm',sampleRate);
          for(const [scope,index,value]of c.base)checked(engine.graph_pitch_config(this.handle,n.id,scope,index,value));
          checked(engine.graph_pitch_performance(this.handle,n.id,c.performance.mode,c.performance.portamento,Number(c.performance.glide==='always')));
          for(const point of c.points)checked(engine.graph_pitch_point(this.handle,n.id,...point));
          for(const point of c.gains)checked(engine.graph_pitch_point(this.handle,n.id,...point));
        }
      }
      for (const c of this.patch.connections) {
        const dest = this.modules.get(c.to.module);
        if (c.kind === 'audio') {
          checked(engine.graph_audio_port(this.handle,c.id,c.from.module,this.modules.get(c.from.module).ports.find(p=>p.id===c.from.port).code,c.to.module,dest.ports.find(p => p.id === c.to.port).code));
          if(c.enabled===false)checked(engine.graph_detector_connection(this.handle,c.id,0));
        }
        else checked(engine.graph_mod(this.handle,c.id,c.from.module,c.to.module,dest.parameters.find(p => p.id === c.to.parameter).code,c.depth,c.offset,Number(c.mapping === 'unipolar')));
      }
      checked(engine.graph_prepare(this.handle));
      for (const event of this.patch.events) this.enqueue(event);
      // A second handle may grow memory during preparation. refresh() belongs off process().
      this.refresh();
    } catch (error) { this.dispose(); throw error; }
  }
  refresh() {
    this.alive();
    this.left = new Float32Array(this.engine.memory.buffer,this.engine.graph_left(this.handle),this.maxBlock);
    this.right = new Float32Array(this.engine.memory.buffer,this.engine.graph_right(this.handle),this.maxBlock);
    this.inputs=new Map();this.kicks=new Map();this.outputs=new Map();
    for(const [id,d]of this.modules){
      this.outputs.set(id,new Float32Array(this.engine.memory.buffer,this.engine.graph_node_ptr(this.handle,id),this.maxBlock*2));
      if(d.hostInput)this.inputs.set(id,new Float32Array(this.engine.memory.buffer,this.engine.graph_input_ptr(this.handle,id),this.maxBlock*2));
      if(d.type==='legacy.percussion')this.kicks.set(id,new Float32Array(this.engine.memory.buffer,this.engine.graph_kick_ptr(this.handle,id),this.maxBlock*2));
    }
  }
  enqueue(event) {
    this.alive();
    checked(this.engine[event.kind==='hit'?'graph_hit':event.kind==='note'?'graph_note':'graph_event'](this.handle,...eventPacket(event,this.modules,this.patch.connections)));
  }
  alive() { if (!this.handle) throw Error('Disposed graph'); }
  render(frames) { this.alive(); if (!Number.isInteger(frames) || frames < 0 || frames > this.maxBlock) throw Error('Invalid frame count'); checked(this.engine.graph_render(this.handle,frames)); }
  stats() { this.alive(); return Object.fromEntries(['frame','late','overflow','applied'].map((key,i) => [key,this.engine.graph_stat(this.handle,i)])); }
  pitchedStats(id){this.alive();if(!['legacy.core','legacy.fm','legacy.piano','legacy.iowa'].includes(this.modules.get(id)?.type))throw Error('Not a pitched node');return Object.fromEntries(['active','steals','dropped','late','frame','peak','latencyFrames','peakActive'].map((key,i)=>[key,this.engine.graph_pitch_stat(this.handle,id,i)]));}
  percussionStats(id){this.alive();if(this.modules.get(id)?.type!=='legacy.percussion')throw Error('Not percussion');return Object.fromEntries(['active','queued','steals','dropped','late','frame','peakActive'].map((key,i)=>[key,this.engine.graph_percussion_stat(this.handle,id,i)]));}
  meters() {this.alive();return Object.fromEntries([...this.modules].filter(([,d])=>d.type==='graph.compressor').map(([id])=>[id,Object.fromEntries(['inputPeak','keyPeak','reductionDb','outputPeak','missingKey','externalKey'].map((key,i)=>[key,this.engine.graph_meter(this.handle,id,i)]))]));}
  pause(value) { this.alive(); this.engine.graph_pause(this.handle,Number(value)); }
  cancel(owner) { this.alive(); if (!uint(owner)) throw Error('Invalid owner'); this.engine.graph_cancel(this.handle,owner); }
  reset() { this.alive(); this.engine.graph_reset(this.handle); }
  dispose() { if (this.handle) { this.engine.graph_free(this.handle); this.handle = 0; this.left = this.right = null; } }
}
